// SPDX-License-Identifier: Apache-2.0
//
// Corpus sweep, twin side (corpus-sweep-8). Runs the JS twin
// (web/twin/verify.mjs) over:
//   * EVERY receipt in fixtures/compute-proof (the estate corpus, including the
//     four short-named fixtures), using the oracle dump generated by
//     `cargo run -p zkprof-verify --bin dump` (fixtures/twin-oracle/*.oracle.json
//     for the short-named ones and the full corpus).
//   * the existing mutation/probe twin-cases (fixtures/twin-cases/*.case.json).
//
// It wires the twin verdict to the crate verdict (fixtures/corpus-sweep/
// crate-verdicts.json) per receipt, and writes the cross-reference for
// docs/TWIN-CORPUS-SWEEP.md plus the raw twin verdicts.
//
// Usage: node web/twin/run-corpus-twin.mjs
// Exit 0 even if a receipt is NOT-VERIFIED (that is a finding, not a crash).

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { verify, deriveDigests } from './verify.mjs';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const repo = path.resolve(__dirname, '..', '..');

const receiptDir = path.join(repo, 'crates', 'zkprof-verify', 'fixtures', 'compute-proof');
const oracleDir = path.join(repo, 'crates', 'zkprof-verify', 'fixtures', 'corpus-sweep', 'oracles');
const fallbackOracleDir = path.join(repo, 'crates', 'zkprof-verify', 'fixtures', 'twin-oracle');
const casesDir = path.join(repo, 'crates', 'zkprof-verify', 'fixtures', 'twin-cases');
const crateVerdictsPath = path.join(repo, 'crates', 'zkprof-verify', 'fixtures', 'corpus-sweep', 'crate-verdicts.json');

function loadJson(p) { return JSON.parse(fs.readFileSync(p, 'utf8')); }
function readJsonIfExists(p) { return fs.existsSync(p) ? loadJson(p) : null; }

const crateVerdicts = loadJson(crateVerdictsPath);
const crateByName = Object.fromEntries(crateVerdicts.map((v) => [v.name, v]));

// The mutation/probe cases' crate verdicts live in the existing
// twin-oracle/crate-verdicts.json (the case-level oracle), not in the
// corpus-sweep receipt verdicts.
const caseVerdictsPath = path.join(fallbackOracleDir, 'crate-verdicts.json');
const caseVerdicts = readJsonIfExists(caseVerdictsPath) || [];
const caseByName = Object.fromEntries(caseVerdicts.map((v) => [`${v.kind}/${v.name}`, v]));

// Every receipt in the corpus. Oracle file is named <name>.oracle.json OR, for
// the short-named fixtures, a pre-existing oracle of the same base name.
const receiptNames = fs
  .readdirSync(receiptDir)
  .filter((f) => f.endsWith('.receipt.json'))
  .map((f) => f.replace(/\.receipt\.json$/, ''))
  .sort();

const results = [];

function runOne(name, receiptObj, oracle) {
  const t0 = Date.now();
  let twin;
  try {
    twin = verify(receiptObj, oracle, {});
  } catch (e) {
    twin = {
      valid: null,
      checks: [{ name: 'twin mechanism', passed: false, detail: `threw: ${e.message}` }],
      notVerified: true,
    };
  }
  const t1 = Date.now();
  const crate = crateByName[name];
  const failed = (twin.checks || []).filter((c) => c.passed === false).map((c) => c.name);
  const crateFailed = crate ? crate.checks.filter((c) => c.passed === false).map((c) => c.name) : [];
  let twinJournalDigest = null;
  try {
    twinJournalDigest = 'sha256:' + deriveDigests(receiptObj).journalDigestHex;
  } catch (e) { /* leave null */ }
  return {
    name,
    crateValid: crate ? crate.valid : null,
    twinValid: twin.valid,
    agree: crate && twin.valid !== null ? crate.valid === twin.valid : false,
    twinNotVerified: !!twin.notVerified,
    twinJournalDigest,
    crateJournalDigest: crate ? crate.journal_digest : null,
    twinFailed: failed,
    crateFailed,
    twinMs: t1 - t0,
  };
}

for (const name of receiptNames) {
  const receiptObj = loadJson(path.join(receiptDir, name + '.receipt.json'));
  // Oracle lives in the (gitignored) corpus-sweep/oracles for the corpus set,
  // or in the committed twin-oracle for the short-named fixtures.
  let oracle = readJsonIfExists(path.join(oracleDir, name + '.oracle.json'));
  if (!oracle) oracle = readJsonIfExists(path.join(fallbackOracleDir, name + '.oracle.json'));
  if (!oracle) {
    results.push({
      name, crateValid: null, twinValid: null, agree: false, twinNotVerified: true,
      twinJournalDigest: null, crateJournalDigest: null,
      twinFailed: ['NO_ORACLE'], crateFailed: [], twinMs: 0,
    });
    continue;
  }
  const oracleRef = {
    control_root: oracle.control_root,
    bn254_control_id: oracle.bn254_control_id,
    verifying_key: oracle.verifying_key,
    claim_digest: oracle.claim_digest,
    public_inputs: oracle.public_inputs,
    proof: oracle.proof,
  };
  results.push(runOne(name, receiptObj, oracleRef));
}

// The mutation/probe twin-cases (no crate oracle verdict in the corpus file, but
// they carry their own expected_image_id and receipt; the crate verdict for
// these lives in fixtures/twin-oracle/crate-verdicts.json).
const caseFiles = fs
  .readdirSync(casesDir)
  .filter((f) => f.endsWith('.case.json'))
  .sort()
  .map((f) => loadJson(path.join(casesDir, f)));

for (const cse of caseFiles) {
  let oracle = readJsonIfExists(path.join(oracleDir, `${cse.name}.oracle.json`));
  if (!oracle) oracle = readJsonIfExists(path.join(fallbackOracleDir, `${cse.name}.oracle.json`));
  if (!oracle) continue;
  const oracleRef = {
    control_root: oracle.control_root,
    bn254_control_id: oracle.bn254_control_id,
    verifying_key: oracle.verifying_key,
    claim_digest: oracle.claim_digest,
    public_inputs: oracle.public_inputs,
    proof: oracle.proof,
  };
  const crate = caseByName[`${cse.kind}/${cse.name}`];
  let twin;
  try {
    twin = verify(cse.receipt, oracleRef, { expectedImageId: cse.expected_image_id ?? undefined });
  } catch (e) {
    twin = { valid: null, checks: [{ name: 'twin mechanism', passed: false, detail: `threw: ${e.message}` }], notVerified: true };
  }
  const failed = (twin.checks || []).filter((c) => c.passed === false).map((c) => c.name);
  const crateFailed = crate ? crate.checks.filter((c) => c.passed === false).map((c) => c.name) : [];
  results.push({
    name: `${cse.kind}/${cse.name}`,
    crateValid: crate ? crate.valid : null,
    twinValid: twin.valid,
    agree: crate && twin.valid !== null ? crate.valid === twin.valid : false,
    twinNotVerified: !!twin.notVerified,
    twinJournalDigest: null,
    crateJournalDigest: crate ? crate.journal_digest : null,
    twinFailed: failed,
    crateFailed,
    twinMs: 0,
  });
}

// write raw twin verdicts
fs.mkdirSync(path.join(repo, 'crates', 'zkprof-verify', 'fixtures', 'corpus-sweep'), { recursive: true });
fs.writeFileSync(
  path.join(repo, 'crates', 'zkprof-verify', 'fixtures', 'corpus-sweep', 'twin-verdicts.json'),
  JSON.stringify(results, null, 2)
);

// console summary
let passPass = 0, failFail = 0, disagree = 0;
for (const r of results) {
  if (r.crateValid === true && r.twinValid === true) passPass++;
  else if (r.crateValid === false && r.twinValid === false) failFail++;
  else if (r.crateValid !== null && r.twinValid !== null) disagree++;
}
console.log(`corpus-twin: ${results.length} total, PASS|PASS=${passPass} FAIL|FAIL=${failFail} disagree=${disagree}`);
console.log('wrote crates/zkprof-verify/fixtures/corpus-sweep/twin-verdicts.json');
